diff --git a/mm/page_alloc.c b/mm/page_alloc.c
index 3a7c12fec906..0a5176a6e9db 100644
--- a/mm/page_alloc.c
+++ b/mm/page_alloc.c
@@ -6513,7 +6513,8 @@ static void setup_per_zone_lowmem_reserve(void);
